head.script:
scwin.trigger1_onclick = function(e) {
    //		 	iframe1.setSrc("UI-3442.xml"); 
    iframe1.setSrc("https://www.google.co.kr/?gfe_rd=cr&ei=sqlHWNyNMqnK8gf5srbwDA&gws_rd=ssl");
};
scwin.iframe1_oniframeload = function(e) {
    //alert("load");
    log = "load";
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 3. 브라우저에서 확인한다.
    //3. 브라우저에서 확인한다.
    //Verify 3. 정상적으로 oniframeload 이벤트가 동작하여 road 팝업창이 생성된다.
    //3. The oniframeload event normally works and a road popup window is created.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "load");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
